int maxSubarrayLen(const vector<int>& a, int k) {
    int n = a.size();
    int l = 0, sum = 0, maxLen = 0;
    for (int r = 0; r < n; r++) {
        sum += a[r];
        while (sum > k && l <= r) {
            sum -= a[l++];
        }
        if (r - l + 1 > maxLen) maxLen = r - l + 1;
    }
    return maxLen;
}

class Solution {
    public int maxSubarrayLen(int[] a, int k) {
        int n = a.length;
        int l = 0, sum = 0, maxLen = 0;
        for (int r = 0; r < n; r++) {
            sum += a[r];
            while (sum > k && l <= r) {
                sum -= a[l++];
            }
            maxLen = Math.max(maxLen, r - l + 1);
        }
        return maxLen;
    }
}

vector<int> nextGreater(const vector<int>& a) {
    int n = a.size();
    vector<int> res(n, -1);
    stack<int> st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.top()] < a[i]) {
            res[st.top()] = a[i];
            st.pop();
        }
        st.push(i);
    }
    return res;
}

class Solution {
    public int[] nextGreater(int[] a) {
        int n = a.length;
        int[] res = new int[n];
        java.util.Arrays.fill(res, -1);
        java.util.ArrayDeque<Integer> st = new java.util.ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && a[st.peek()] < a[i]) {
                res[st.pop()] = a[i];
            }
            st.push(i);
        }
        return res;
    }
}

vector<int> maxSlidingWindow(const vector<int>& a, int k) {
    int n = a.size();
    deque<int> dq;
    vector<int> ans;
    for (int i = 0; i < n; i++) {
        while (!dq.empty() && dq.front() <= i - k) dq.pop_front();
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
        dq.push_back(i);
        if (i >= k - 1) ans.push_back(a[dq.front()]);
    }
    return ans;
}

class Solution {
    public int[] maxSlidingWindow(int[] a, int k) {
        int n = a.length;
        java.util.Deque<Integer> dq = new java.util.ArrayDeque<>();
        int[] ans = new int[n - k + 1];
        for (int i = 0; i < n; i++) {
            while (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();
            while (!dq.isEmpty() && a[dq.peekLast()] <= a[i]) dq.pollLast();
            dq.addLast(i);
            if (i >= k - 1) ans[i - k + 1] = a[dq.peekFirst()];
        }
        return ans;
    }
}

struct DSU {
