vector<long long> dijkstra(int start, int V, const vector<vector<pair<int, int>>>& g) {
    vector<long long> dist(V, 1e18);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    dist[start] = 0;
    pq.push({0, start});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : g[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

class Solution {
    static class Edge { int to, weight; Edge(int t, int w) { to = t; weight = w; } }
    public long[] dijkstra(int start, int V, java.util.List<java.util.List<Edge>> g) {
        long[] dist = new long[V];
        java.util.Arrays.fill(dist, Long.MAX_VALUE);
        java.util.PriorityQueue<long[]> pq = new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        dist[start] = 0;
        pq.add(new long[]{0, start});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int)cur[1];
            if (d > dist[u]) continue;
            for (Edge e : g.get(u)) {
                if (dist[u] + e.weight < dist[e.to]) {
                    dist[e.to] = dist[u] + e.weight;
                    pq.add(new long[]{dist[e.to], e.to});
                }
            }
        }
        return dist;
    }
}

vector<int> topoSort(int V, const vector<vector<int>>& g) {
    vector<int> in_degree(V, 0);
    for (int u = 0; u < V; u++) {
        for (int v : g[u]) in_degree[v]++;
    }
    queue<int> q;
    for (int i = 0; i < V; i++) {
        if (in_degree[i] == 0) q.push(i);
    }
    vector<int> order;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u);
        for (int v : g[u]) {
            if (--in_degree[v] == 0) q.push(v);
        }
    }
    return order;
}

class Solution {
    public java.util.List<Integer> topoSort(int V, java.util.List<java.util.List<Integer>> g) {
        int[] inDegree = new int[V];
        for (int u = 0; u < V; u++) {
            for (int v : g.get(u)) inDegree[v]++;
        }
        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        for (int i = 0; i < V; i++) if (inDegree[i] == 0) q.add(i);
        java.util.List<Integer> order = new java.util.ArrayList<>();
        while (!q.isEmpty()) {
            int u = q.poll();
            order.add(u);
            for (int v : g.get(u)) {
                if (--inDegree[v] == 0) q.add(v);
            }
        }
        return order;
    }
}

