struct SparseTable {
    int n, K;
    vector<vector<int>> st;
    SparseTable(const vector<int>& a) : n(a.size()), K(20), st(20, vector<int>(n)) {
        st[0] = a;
        for (int j = 1; j < K; j++) {
            for (int i = 0; i + (1 << j) <= n; i++) {
                st[j][i] = min(st[j - 1][i], st[j - 1][i + (1 << (j - 1))]);
            }
        }
    }
    int query(int l, int r) {
        int j = 31 - __builtin_clz(r - l + 1);
        return min(st[j][l], st[j][r - (1 << j) + 1]);
    }
};

class SparseTable {
    int n, K;
    int[][] st;
    public SparseTable(int[] a) {
        n = a.length;
        K = 20;
        st = new int[K][n];
        System.arraycopy(a, 0, st[0], 0, n);
        for (int j = 1; j < K; j++) {
            for (int i = 0; i + (1 << j) <= n; i++) {
                st[j][i] = Math.min(st[j - 1][i], st[j - 1][i + (1 << (j - 1))]);
            }
        }
    }
    public int query(int l, int r) {
        int len = r - l + 1;
        int j = 31 - Integer.numberOfLeadingZeros(len);
        return Math.min(st[j][l], st[j][r - (1 << j) + 1]);
    }
}

vector<int> kmp(const string& s, const string& pattern) {
    int n = s.size(), m = pattern.size();
    vector<int> pi(m, 0);
    for (int i = 1; i < m; i++) {
        int j = pi[i - 1];
        while (j > 0 && pattern[i] != pattern[j]) j = pi[j - 1];
        if (pattern[i] == pattern[j]) j++;
        pi[i] = j;
    }
    vector<int> matches;
    int j = 0;
    for (int i = 0; i < n; i++) {
        while (j > 0 && s[i] != pattern[j]) j = pi[j - 1];
        if (s[i] == pattern[j]) j++;
        if (j == m) { matches.push_back(i - m + 1); j = pi[j - 1]; }
    }
    return matches;
}

class Solution {
    public java.util.List<Integer> kmp(String s, String pattern) {
        int n = s.length(), m = pattern.length();
        int[] pi = new int[m];
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && pattern.charAt(i) != pattern.charAt(j)) j = pi[j - 1];
            if (pattern.charAt(i) == pattern.charAt(j)) j++;
            pi[i] = j;
        }
        java.util.List<Integer> matches = new java.util.ArrayList<>();
        int j = 0;
        for (int i = 0; i < n; i++) {
            while (j > 0 && s.charAt(i) != pattern.charAt(j)) j = pi[j - 1];
            if (s.charAt(i) == pattern.charAt(j)) j++;
            if (j == m) { matches.add(i - m + 1); j = pi[j - 1]; }
        }
        return matches;
    }
}

