struct Edge { int u, v; long long weight; };
bool cmp(const Edge& a, const Edge& b) { return a.weight < b.weight; }
long long kruskal_mst(int n, vector<Edge>& edges, vector<int>& parent) {
    std::sort(edges.begin(), edges.end(), cmp);
    long long mst_cost = 0;
    auto find = [&](auto& self, int i) -> int {
        return parent[i] == i ? i : parent[i] = self(self, parent[i]);
    };
    for (const auto& e : edges) {
        int root_u = find(find, e.u), root_v = find(find, e.v);
        if (root_u != root_v) {
            parent[root_u] = root_v;
            mst_cost += e.weight;
        }
    }
    return mst_cost;
}

class Edge { int u, v; long long weight; }
class Solution {
    int find(int[] parent, int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent, parent[i]);
    }
    public long kruskal_mst(int n, List<Edge> edges, int[] parent) {
        edges.sort((a, b) -> Long.compare(a.weight, b.weight));
        long cost = 0;
        for (Edge e : edges) {
            int root_u = find(parent, e.u);
            int root_v = find(parent, e.v);
            if (root_u != root_v) {
                parent[root_u] = root_v;
                cost += e.weight;
            }
        }
        return cost;
    }
}

int up[200005][20];
int depth[200005];
int get_lca(int u, int v) {
    if (depth[u] < depth[v]) swap(u, v);
    for (int j = 19; j >= 0; j--) {
        if (depth[u] - (1 << j) >= depth[v]) u = up[u][j];
    }
    if (u == v) return u;
    for (int j = 19; j >= 0; j--) {
        if (up[u][j] != up[v][j]) {
            u = up[u][j];
            v = up[v][j];
        }
    }
    return up[u][0];
}

class Solution {
    int[][] up = new int[200005][20];
    int[] depth = new int[200005];
    public int get_lca(int u, int v) {
        if (depth[u] < depth[v]) { int t = u; u = v; v = t; }
        for (int j = 19; j >= 0; j--) {
            if (depth[u] - (1 << j) >= depth[v]) u = up[u][j];
        }
        if (u == v) return u;
        for (int j = 19; j >= 0; j--) {
            if (up[u][j] != up[v][j]) {
                u = up[u][j];
                v = up[v][j];
            }
        }
        return up[u][0];
    }
}

vector<int> z_algorithm(const string& s) {
    int n = s.length();
    vector<int> z(n, 0);
    int l = 0, r = 0;
    for (int i = 1; i < n; i++) {
        if (i <= r) z[i] = min(r - i + 1, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] - 1 > r) {
            l = i;
            r = i + z[i] - 1;
        }
    }
    return z;
}

class Solution {
    public int[] z_algorithm(String s) {
        int n = s.length();
        int[] z = new int[n];
        int l = 0, r = 0;
        for (int i = 1; i < n; i++) {
            if (i <= r) z[i] = Math.min(r - i + 1, z[i - l]);
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
            if (i + z[i] - 1 > r) {
                l = i;
                r = i + z[i] - 1;
            }
        }
        return z;
    }
}

struct PolyHash {
    vector<long long> hash, p_pow;
    const int MOD = 1000000007;
    const int BASE = 313;
    void build(const string& s) {
        int n = s.size();
        hash.assign(n + 1, 0);
        p_pow.assign(n + 1, 1);
        for (int i = 0; i < n; i++) {
            hash[i + 1] = (hash[i] * BASE + s[i]) % MOD;
            p_pow[i + 1] = (p_pow[i] * BASE) % MOD;
        }
    }
};

