long long power(long long base, long long exp) {
    long long res = 1;
    for (long long i = exp; i > 0; i /= 2) {
        if (i % 2 == 1) res = (res * base) % 1000000007;
        base = (base * base) % 1000000007;
    }
    return res;
}

