void bfs_island(int r, int c, vector<vector<char>>& grid, vector<vector<bool>>& visited) {
    int m = grid.size(), n = grid[0].size();
    queue<pair<int, int>> q;
    q.push({r, c});
    visited[r][c] = true;
    int dr[] = {0, 0, 1, -1};
    int dc[] = {1, -1, 0, 0};
    while (!q.empty()) {
        auto [cr, cc] = q.front(); q.pop();
        for (int i = 0; i < 4; i++) {
            int nr = cr + dr[i], nc = cc + dc[i];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] == '1') {
                visited[nr][nc] = true;
                q.push({nr, nc});
            }
        }
    }
}

class Solution {
    public void bfs_island(int r, int c, char[][] grid, boolean[][] visited) {
        int m = grid.length, n = grid[0].length;
