int ans = 0;
pair<int, int> dfs(int u, int p, const vector<vector<int>>& adj, const string& s) {
    int w = (s[u] == 'W'), b = (s[u] == 'B');
    for (int v : adj[u]) {
        if (v != p) {
            auto [cw, cb] = dfs(v, u, adj, s);
            w += cw; b += cb;
        }
    }
    dp[u] = w - b;
    if (w == b) ans++;
    return {w, b};
}

class Solution {
    int ans = 0;
    int[] dp = new int[200005];
    int[] dfs(int u, int p, List<List<Integer>> adj, String s) {
        int w = (s.charAt(u) == 'W' ? 1 : 0);
        int b = (s.charAt(u) == 'B' ? 1 : 0);
        for (int v : adj.get(u)) {
            if (v != p) {
                int[] res = dfs(v, u, adj, s);
                w += res[0]; b += res[1];
            }
        }
        dp[u] = w - b;
        if (w == b) ans++;
        return new int[]{w, b};
    }
}

